import * as T from './vendor/three.module.js';
import {loadCharacterAssets,makeCharacter,disposeCharacter,animateCharacter,appearanceDefaults} from './character.js';
import {animateActivity} from './activity-pose.js';
import {lightPortrait} from './portrait-lighting.js';
import {skinToneMarkup,bindSkinTones} from './skin-tones.js';
import {migrateWardrobe,previewFashion} from './wardrobe-state.js';
import {FASHION,FASHION_ITEMS,starterOutfit} from './fashion-catalogue.js';

// Deliberately no storage, purchase, save or game-state access in this study.
const $=id=>document.getElementById(id);
const samples={female:{name:'Amara',hair:['hair-bob','hair-braids','hair-bun'],native:'native-iro'},male:{name:'Bode',hair:['hair-fade','hair-locs','hair-cornrows'],native:'native-senator'}};
let sex='female',look='casual',state,model,yaw=.18,focus=1.22,distance=5.5,pose='idle',elapsed=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,queued=false,closed=false;
const scene=new T.Scene();lightPortrait(scene);
const camera=new T.PerspectiveCamera(32,1,.1,30);
let renderer;try{renderer=new T.WebGLRenderer({antialias:true});}catch(error){$('loading').textContent='This browser could not start the 3D preview. Try a browser with WebGL enabled.';throw error;}renderer.setPixelRatio(Math.min(devicePixelRatio,1.25));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1;
$('stage').appendChild(renderer.domElement);
function resetState(){state={...appearanceDefaults,sex,characterStyle:'natural',outfit:'streetwear',hair:sex==='female'?'bob':'fade',shirt:'#e4ddd0',bottom:'#465a50',accessory:sex==='female'?'earrings':'none',makeup:{brows:0,liner:0,lipstick:0,blush:0,lipColour:'#963f51'}};migrateWardrobe(state,{});look=starterOutfit(sex);state=previewFashion(state,look);}
function replaceModel(){if(closed)return;if(model){scene.remove(model);disposeCharacter(model);}model=makeCharacter(state);scene.add(model);elapsed=0;if(pose==='sit')animateActivity(model,'sit',.05,.1);else animateCharacter(model,pose==='walk'?.2:0,pose==='walk');}
function queueModel(){clearTimeout(queued);queued=setTimeout(()=>{queued=false;replaceModel();},120);}
function cards(){const sample=samples[sex];$('look-caption').textContent=sample.name+' · '+FASHION[look].name;$('hair-cards').innerHTML=sample.hair.map(id=>`<button id="study-${id}" aria-pressed="${(state.wardrobe.equipped.hair||sample.hair[0])===id}"><img loading="lazy" decoding="async" src="assets/fashion-review/${sex}-${id}.webp" alt="${FASHION[id].name}"><span>${FASHION[id].name}</span></button>`).join('');for(const id of sample.hair)$('study-'+id).onclick=()=>{state=previewFashion(state,id);cards();queueModel();};const outfits=FASHION_ITEMS.filter(i=>i.slot==='full'&&i.implemented);$('study-outfit-count').textContent=outfits.length+' outfits · '+outfits.filter(i=>i.sex==='female').length+' female / '+outfits.filter(i=>i.sex==='male').length+' male';$('outfit-cards').innerHTML=outfits.map(i=>`<button id="look-${i.id}" aria-pressed="${look===i.id}"><img loading="lazy" decoding="async" src="${i.thumbnail}" alt="${i.name}"><span>${i.name}<small>${i.sex==='male'?'Male':'Female'} fit</small></span></button>`).join('');for(const i of outfits)$('look-'+i.id).onclick=()=>{if(i.sex!==sex){sex=i.sex;resetState();}look=i.id;state=previewFashion(state,i.id);controls();queueModel();};}
function controls(){for(const s of ['female','male'])$(s).setAttribute('aria-pressed',String(s===sex));$('build').value=state.build;$('face-shape').value=state.face;$('hair-colour').value=state.hairColor;$('accessory').value=state.accessory;$('skin-options').innerHTML=skinToneMarkup(state.skin);bindSkinTones($('skin-options'),colour=>{state.skin=colour;queueModel();});cards();makeupControls();}
function makeupControls(){const labels={brows:'Brows',liner:'Eyeliner',lipstick:'Lipstick',blush:'Blush'};$('makeup-controls').innerHTML=Object.entries(labels).map(([key,label])=>`<label>${label}<input id="makeup-${key}" type="range" min="0" max="1" step=".05" value="${state.makeup[key]}"><output id="value-${key}">${Math.round(state.makeup[key]*100)}%</output></label>`).join('');for(const key of Object.keys(labels))$('makeup-'+key).oninput=()=>{state.makeup[key]=Number($('makeup-'+key).value);$('value-'+key).textContent=Math.round(state.makeup[key]*100)+'%';queueModel();};$('lip-colour').value=state.makeup.lipColour;}
function draw(){if(!model)return;const width=$('stage').clientWidth,height=$('stage').clientHeight;if(renderer.domElement.width!==Math.round(width*renderer.getPixelRatio())||renderer.domElement.height!==Math.round(height*renderer.getPixelRatio())){camera.aspect=width/height;camera.updateProjectionMatrix();renderer.setSize(width,height,false);}model.rotation.y=yaw;model.position.y=pose==='sit'?.63:0;camera.position.set(0,focus+.06,distance*Math.max(1,.72/camera.aspect));camera.lookAt(0,focus,0);renderer.render(scene,camera);}
let last=performance.now();function frame(now){if(closed)return;const dt=Math.min(.05,(now-last)/1000);last=now;if(!document.hidden&&model){if(!paused){elapsed+=dt;pose==='sit'?animateActivity(model,'sit',dt,elapsed):animateCharacter(model,dt,pose==='walk');}draw();}requestAnimationFrame(frame);}
try{await loadCharacterAssets();resetState();replaceModel();controls();$('loading').remove();requestAnimationFrame(frame);}catch(error){$('loading').textContent='The preview could not load. Reload to try again.';console.error(error);}
for(const s of ['female','male'])$(s).onclick=()=>{sex=s;resetState();controls();queueModel();};$('reset').onclick=()=>{resetState();controls();queueModel();};$('build').onchange=()=>{state.build=$('build').value;queueModel();};$('face-shape').onchange=()=>{state.face=$('face-shape').value;queueModel();};$('accessory').onchange=()=>{state.accessory=$('accessory').value;queueModel();};$('hair-colour').oninput=()=>{state.hairColor=$('hair-colour').value;queueModel();};$('lip-colour').oninput=()=>{state.makeup.lipColour=$('lip-colour').value;queueModel();};$('reset-makeup').onclick=()=>{state.makeup={brows:0,liner:0,lipstick:0,blush:0,lipColour:'#963f51'};makeupControls();queueModel();};$('pose').onchange=()=>{pose=$('pose').value;queueModel();};$('pause').setAttribute('aria-pressed',String(paused));$('pause').textContent=paused?'Resume':'Pause';$('pause').onclick=()=>{paused=!paused;$('pause').setAttribute('aria-pressed',String(paused));$('pause').textContent=paused?'Resume':'Pause';};$('turn-left').onclick=()=>yaw-=Math.PI/4;$('turn-right').onclick=()=>yaw+=Math.PI/4;$('full').onclick=()=>{focus=1.22;distance=5.5;$('zoom').value=distance;};$('face').onclick=()=>{focus=2.14;distance=1.4;$('zoom').value=distance;};$('zoom').oninput=()=>distance=Number($('zoom').value);
let pointer=null,px=0;renderer.domElement.addEventListener('pointerdown',e=>{pointer=e.pointerId;px=e.clientX;renderer.domElement.setPointerCapture(pointer);});renderer.domElement.addEventListener('pointermove',e=>{if(e.pointerId===pointer){yaw+=(e.clientX-px)*.012;px=e.clientX;}});for(const event of ['pointerup','pointercancel','lostpointercapture'])renderer.domElement.addEventListener(event,()=>pointer=null);
$('capture').onclick=()=>{if(queued){clearTimeout(queued);queued=false;replaceModel();}draw();const a=document.createElement('a');a.download='city-and-us-'+sex+'-'+look+'.png';a.href=renderer.domElement.toDataURL('image/png');a.click();$('notice').textContent='Preview image saved from your browser.';};
addEventListener('pagehide',()=>{closed=true;clearTimeout(queued);if(model)disposeCharacter(model);renderer.dispose();renderer.forceContextLoss();});
